    correctKey: 'B',
    explanation: '正しい。契約者＝被保険者の死亡保険金はみなし相続財産として相続税の対象となり、相続人が受け取れば非課税枠が使える。\n死亡保険金は契約者・被保険者・受取人の関係で相続税・所得税・贈与税に分かれる。入院給付金など身体の傷害に基因する給付金は非課税。一時払養老保険等の5年以内の差益は源泉分離課税となる。\n【図解】\n★死亡保険金の課税関係（契約者→被保険者→受取人）\n○A→A→相続人＝相続税（500万円×法定相続人数の非課税枠）\n○A→B→A＝所得税（一時所得）\n○A→B→C＝贈与税\n×入院・手術・通院給付金、リビング・ニーズ給付金→非課税\n⚠一時払養老等を5年以内に解約→金融類似商品として20.315%源泉分離',
