    explanation: '誤り。資産計上額との差額は益金となり、法人税の課税対象となる。\n法人契約では受取人・保険の種類・解約返戻率により経理処理が異なる。ハーフタックスプランは普遍的加入を要件に保険料の2分の1を福利厚生費にできる。2019年改正で返戻率区分による資産計上ルールが導入された。\n【図解】\n★ハーフタックスプラン（養老保険）\n○契約者＝法人／被保険者＝全役員・従業員\n○死亡保険金→遺族／満期保険金→法人\n→保険料の1/2を福利厚生費（損金）、1/2を資産計上\n⚠特定の者のみ加入→給与扱いのおそれ\n→定期保険等：最高解約返戻率50%超は一部資産計上（2019年改正）',
