    correctKey: 'C',
    explanation: '誤り。払込期間中の解約返戻金を低く抑える代わりに、保険料は通常の終身保険より安い。\n定期保険は掛捨てで満期保険金がない。終身保険は一生涯保障で解約返戻金が増えていく。養老保険は死亡保険金と満期保険金が同額。収入保障保険は年金形式で受け取り、一時金受取では総額が少なくなる。\n【図解】\n★死亡保障商品の比較\n○定期保険→期間限定・掛捨て・保険料安い\n○終身保険→一生涯保障・解約返戻金あり\n○養老保険→死亡保険金＝満期保険金\n→収入保障保険：年金形式で受取り、一時金だと受取総額は減る\n⚠低解約返戻金型：払込期間中の返戻金を低く抑えて保険料を安く',
