    correctKey: 'C',
    explanation: '正しい。少額短期保険の保険料は生命保険料控除（および地震保険料控除）の対象外である。\n2012年以降の新契約は一般・介護医療・個人年金の3区分で、所得税は各4万円・合計12万円、住民税は各2.8万円・合計7万円が限度。傷害特約等の保険料は新契約では対象外。\n【図解】\n★生命保険料控除（2012年以降の新契約）\n○一般＋介護医療＋個人年金の3区分\n→所得税：各最高4万円・合計12万円\n→住民税：各最高2.8万円・合計7万円\n×傷害特約・災害割増特約の保険料→対象外\n⚠税制適格特約のない個人年金→一般の区分で控除',
    difficulty: 'standard',
